use rand::SeedableRng;
use rand_chacha::ChaCha8Rng;
use rand_distr::{Normal, Distribution};
fn main(){
    let mut rng = ChaCha8Rng::seed_from_u64(42);
    let normal = Normal::new(500.0_f64, 20.0_f64).unwrap();
    let (mut a, mut b) = (1_000_000.0_f64, 0.0_f64);
    let (la, lb, dt) = (0.1_f64, 0.05_f64, 1.0_f64);
    let mut hist = [0i64; 40];
    for _ in 0..60 {
        let decay_a = la*a*dt;
        let decay_b = lb*b*dt;
        a = a - decay_a;
        b = b + decay_a - decay_b;
        let n = (decay_b*0.1).floor() as i64;
        for _ in 0..n {
            let e: f64 = normal.sample(&mut rng);
            if e >= 400.0 && e < 600.0 {
                let idx = ((e-400.0)/5.0).floor() as usize;
                hist[idx]+=1;
            }
        }
    }
    let mut out=String::new();
    for i in 0..40 { out.push_str(&format!("{},{}\n", 400+i*5, hist[i])); }
    std::fs::write("/home/user/spectrum.csv", out).unwrap();
}
